  FILTER (?zl IN ("Perimeter_mid_ZN_1","Perimeter_bot_ZN_2"))
  ?p ?rel ?zone .
  ?p a ?class .
  OPTIONAL { ?p rdfs:label ?lbl }
}

SELECT ?s ?zl ?tsid WHERE {
  ?zone rdfs:label ?zl .
  FILTER (?zl IN ("Perimeter_mid_ZN_1","Perimeter_bot_ZN_2"))
  ?s ?rel ?zone .
  FILTER (regex(str(?s), "Occupancy"))
  OPTIONAL { ?s ref:hasTimeseriesId ?tsid }
}

